#!/usr/bin/env bash
# Builds the Java SDK of demo:client@1.0.0 from the sources next to this script
# (generated by wabi-wit-gen — DO NOT EDIT):
#
#   build/demo-client.jar            desktop/server: Panama (JDK 22+) and JNI bindings
#   build/demo-client-android.jar    Android: JNI binding only, Java 17 bytecode
#   build/libdemo_client_jni.so|.dylib   JNI shim for this host (Android: jni/CMakeLists.txt)
#
#   build.sh [<output dir>]    default: build/ next to this script
#
# Everything except the Panama binding is compiled with --release 17, so the
# same sources serve Android; the Panama classes (PanamaAbi, NativeAbi) are
# compiled with --release 22 and left out of the Android jar.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="${1:-$HERE/build}"
mkdir -p "$OUT" && OUT="$(cd "$OUT" && pwd)"
rm -rf "$OUT/classes" "$OUT/jni" && mkdir -p "$OUT/classes" "$OUT/jni"
SOURCES=$(find "$HERE" -name '*.java' -not -path "$OUT/*")
PANAMA=$(echo "$SOURCES" | grep -e '/PanamaAbi.java$' -e '/NativeAbi.java$')
COMMON=$(echo "$SOURCES" | grep -v -e '/PanamaAbi.java$' -e '/NativeAbi.java$')
LINT="-Xlint:all,-serial,-restricted -Werror"
javac --release 17 $LINT -h "$OUT/jni" -d "$OUT/classes" $COMMON
javac --release 22 $LINT -cp "$OUT/classes" -d "$OUT/classes" $PANAMA
jar --create --file "$OUT/demo-client.jar" -C "$OUT/classes" .
jar --create --file "$OUT/demo-client-android.jar" \
  $(cd "$OUT/classes" && find . -name '*.class' ! -name 'PanamaAbi*' ! -name 'NativeAbi*' | sed 's|^|-C '"$OUT/classes"' |')
echo "built $OUT/demo-client.jar, $OUT/demo-client-android.jar"

# JNI shim for this host. -include makes the compiler check every JNI function
# against the signatures javac generated from JniAbi.java.
JAVA_HOME="${JAVA_HOME:-$(dirname "$(dirname "$(readlink -f "$(command -v javac)")")")}"
case "$(uname -s)" in Darwin) OS=darwin EXT=dylib ;; *) OS=linux EXT=so ;; esac
if [ -f "$JAVA_HOME/include/jni.h" ]; then
  cc -std=c11 -O2 -Wall -Wextra -Werror -fPIC -shared \
    -I"$JAVA_HOME/include" -I"$JAVA_HOME/include/$OS" -I"$HERE/../abi" \
    -include "$(ls "$OUT"/jni/*_JniAbi.h)" \
    -o "$OUT/libdemo_client_jni.$EXT" "$HERE/jni/demo_client_jni.c" -ldl -lpthread
  echo "built $OUT/libdemo_client_jni.$EXT"
else
  echo "SKIP JNI shim: no jni.h under $JAVA_HOME"
fi
